329→func hasCreate(actions []action) bool {
330→	for _, a := range actions {
331→		if a.kind == "create" {
332→			return true
333→		}
334→	}
335→	return false
336→}
337→
338→func hasModify(actions []action) bool {
339→	for _, a := range actions {
340→		if a.kind == "modify" {
341→			return true
342→		}
343→	}
344→	return false
345→}
346→
347→func hasModifyOnly(actions []action) bool {
348→	if len(actions) == 0 {
349→		return false
350→	}
351→	for _, a := range actions {
352→		if a.kind != "modify" {
353→			return false
354→		}
355→	}
356→	return true
357→}
358→
359→// interleaveCommits inserts a commit after each create/modify action.
360→func interleaveCommits(actions []action) []action {
361→	var result []action
362→	for _, a := range actions {
363→		result = append(result, a)
364→		if a.kind == "create" || a.kind == "modify" {
365→			result = append(result, action{kind: "commit"})
366→		}
367→	}
368→	return result
369→}
370→
371→func extractTopic(prompt string) string {
372→	if m := topicRe.FindStringSubmatch(prompt); m != nil {
373→		return strings.TrimSpace(m[1])
374→	}
375→	return "the topic"
376→}
377→
378→func executeActions(dir string, actions []action) {
379→	var pendingFiles []string
380→	for _, a := range actions {
381→		switch a.kind {
382→		case "create":
383→			createFile(dir, a.path, a.content)
384→			pendingFiles = append(pendingFiles, a.path)
385→		case "modify":
386→			modifyFile(dir, a.path, a.content)
387→			pendingFiles = append(pendingFiles, a.path)
388→		case "delete":
389→			deleteFile(dir, a.path)
390→			pendingFiles = append(pendingFiles, a.path)
391→		case "commit":
392→			gitCommit(dir, pendingFiles)
393→			pendingFiles = nil
394→		}
395→	}
396→}
