398→func createFile(dir, path, content string) {
399→	abs := filepath.Join(dir, path)
400→	if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
401→		fmt.Fprintf(os.Stderr, "mkdir %s: %v\n", filepath.Dir(abs), err)
402→		return
403→	}
404→	if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
405→		fmt.Fprintf(os.Stderr, "write %s: %v\n", abs, err)
406→	}
407→}
408→
409→func modifyFile(dir, path, appendContent string) {
410→	abs := filepath.Join(dir, path)
411→	existing, _ := os.ReadFile(abs)
412→	content := string(existing) + "\n" + appendContent
413→	if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
414→		fmt.Fprintf(os.Stderr, "write %s: %v\n", abs, err)
415→	}
416→}
417→
418→func deleteFile(dir, path string) {
419→	abs := filepath.Join(dir, path)
420→	if err := os.Remove(abs); err != nil {
421→		fmt.Fprintf(os.Stderr, "remove %s: %v\n", abs, err)
422→	}
423→}
424→
425→func gitCommit(dir string, files []string) {
426→	if len(files) == 0 {
427→		gitRun(dir, "add", ".")
428→	} else {
429→		gitRun(dir, append([]string{"add", "--"}, files...)...)
430→	}
431→	gitRun(dir, "commit", "-m", "Vogon agent commit")
432→}
433→
434→func gitRun(dir string, args ...string) {
435→	cmd := exec.Command("git", args...)
436→	cmd.Dir = dir
437→	cmd.Stdout = os.Stdout
438→	cmd.Stderr = os.Stderr
439→	// Signal that this is a non-interactive agent — git hooks should not
440→	// attempt TTY prompts. GIT_TERMINAL_PROMPT is the standard git env var
441→	// for this (same approach used by Factory AI Droid).
442→	cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0")
443→	if err := cmd.Run(); err != nil {
444→		fmt.Fprintf(os.Stderr, "git %s: %v\n", strings.Join(args, " "), err)
445→	}
446→}
