448→// --- Hook Firing ---
449→
450→func fireHook(dir, hookName string, payload any) {
451→	data, err := json.Marshal(payload)
452→	if err != nil {
453→		fmt.Fprintf(os.Stderr, "marshal hook payload: %v\n", err)
454→		return
455→	}
456→
457→	cmd := exec.Command("entire", "hooks", "vogon", hookName)
458→	cmd.Dir = dir
459→	cmd.Stdin = bytes.NewReader(data)
460→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
461→	// Capture output but don't show it — hooks may output banners
462→	out, err := cmd.CombinedOutput()
463→	if err != nil {
464→		fmt.Fprintf(os.Stderr, "hook %s failed: %v\n%s\n", hookName, err, out)
465→	}
466→}
