470→func setupTranscript(sessionID string) string {
471→	home, err := os.UserHomeDir()
472→	if err != nil {
473→		fatal("home dir: %v", err)
474→	}
475→	transcriptDir := filepath.Join(home, ".vogon", "sessions")
476→	if err := os.MkdirAll(transcriptDir, 0o755); err != nil {
477→		fatal("mkdir transcript dir: %v", err)
478→	}
