 95→// stableContent returns the content with the last few lines stripped,
 96→// so that TUI status bar updates don't prevent the settle timer.
 97→func stableContent(content string) string {
 98→	lines := strings.Split(content, "\n")
 99→	if len(lines) > 3 {
100→		lines = lines[:len(lines)-3]
101→	}
102→	return strings.Join(lines, "\n")
103→}
