160→// IsPaneDead returns true if the process inside the tmux pane has exited.
161→// This relies on the remain-on-exit option being set (which NewTmuxSession does).
162→func (s *TmuxSession) IsPaneDead() bool {
163→	cmd := exec.Command("tmux", "display-message", "-t", s.name, "-p", "#{pane_dead}")
164→	out, err := cmd.Output()
165→	if err != nil {
166→		// If tmux itself fails (e.g. session/pane no longer exists),
167→		// treat it as dead so WaitFor doesn't poll until timeout.
168→		return true
169→	}
170→	return strings.TrimSpace(string(out)) == "1"
171→}
