350→func hookCmdPrefix(localDev, absolutePath bool) (string, error) {
351→	if localDev {
352→		return "go run ./cmd/entire/main.go", nil
353→	}
354→	if absolutePath {
355→		exe, err := os.Executable()
356→		if err != nil {
357→			return "", fmt.Errorf("--absolute-git-hook-path: failed to resolve binary path: %w", err)
358→		}
359→		resolved, err := filepath.EvalSymlinks(exe)
360→		if err != nil {
361→			return "", fmt.Errorf("--absolute-git-hook-path: failed to resolve symlinks for %s: %w", exe, err)
362→		}
363→		return shellQuote(resolved), nil
364→	}
365→	return "entire", nil
366→}
